-- ==============================================================================
-- Schema da Tabela 'reservas' para o Supabase (PostgreSQL)
-- ==============================================================================

CREATE TABLE IF NOT EXISTS public.reservas (
  id TEXT PRIMARY KEY,
  quadra_id TEXT NOT NULL,
  nome_cliente TEXT NOT NULL DEFAULT '',
  whatsapp_cliente TEXT NOT NULL DEFAULT '',
  telefone_cliente TEXT DEFAULT '',
  cpf_cliente TEXT NOT NULL DEFAULT '',
  data DATE NOT NULL,
  horarios TEXT[] NOT NULL DEFAULT '{}',
  hora_inicio TEXT NOT NULL,
  hora_fim TEXT NOT NULL,
  valor_total NUMERIC(10, 2) NOT NULL DEFAULT 0,
  valor_sinal NUMERIC(10, 2) NOT NULL DEFAULT 0,
  valor_pendente NUMERIC(10, 2) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'em_processamento',
  status_whatsapp TEXT NOT NULL DEFAULT 'nao_enviado',
  esporte TEXT,
  observacoes TEXT,
  criada_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Índices para consultas otimizadas da agenda e prevenção de double booking
CREATE INDEX IF NOT EXISTS idx_reservas_data_quadra ON public.reservas (data, quadra_id);
CREATE INDEX IF NOT EXISTS idx_reservas_status ON public.reservas (status);

-- Habilitar Row Level Security (RLS)
ALTER TABLE public.reservas ENABLE ROW LEVEL SECURITY;

-- Políticas de acesso para a Anon Key
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'reservas' AND policyname = 'Permitir leitura pública de reservas'
  ) THEN
    CREATE POLICY "Permitir leitura pública de reservas"
      ON public.reservas FOR SELECT
      USING (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'reservas' AND policyname = 'Permitir inserção de novas reservas'
  ) THEN
    CREATE POLICY "Permitir inserção de novas reservas"
      ON public.reservas FOR INSERT
      WITH CHECK (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'reservas' AND policyname = 'Permitir atualização de reservas'
  ) THEN
    CREATE POLICY "Permitir atualização de reservas"
      ON public.reservas FOR UPDATE
      USING (true)
      WITH CHECK (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE tablename = 'reservas' AND policyname = 'Permitir remoção de reservas'
  ) THEN
    CREATE POLICY "Permitir remoção de reservas"
      ON public.reservas FOR DELETE
      USING (true);
  END IF;
END $$;

-- Habilita Realtime na publicação padrão do Supabase
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.reservas;
  END IF;
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

import { createClient } from "@supabase/supabase-js";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || "";
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || "";

/**
 * Retorna true se as variáveis de ambiente necessárias para conexão
 * com o Supabase estiverem devidamente preenchidas.
 */
export const isSupabaseConfigured = (): boolean => {
  return Boolean(
    supabaseUrl &&
    supabaseAnonKey &&
    !supabaseUrl.includes("sua-url-supabase") &&
    !supabaseAnonKey.includes("sua-chave-anon-key")
  );
};

/**
 * Cliente Supabase singleton configurado.
 * Quando não configurado no ambiente, usa placeholders seguros para evitar erros de inicialização.
 */
export const supabase = createClient(
  isSupabaseConfigured() ? supabaseUrl : "https://placeholder-project.supabase.co",
  isSupabaseConfigured() ? supabaseAnonKey : "placeholder-anon-key",
  {
    auth: {
      persistSession: false,
    },
  }
);

import type { Reserva, StatusReserva, StatusWhatsApp } from "@/store/useReservasStore";
import type { Esporte } from "@/lib/quadras";

export interface ReservaDbRow {
  id: string;
  quadra_id?: string;
  quadraId?: string;
  nome_cliente?: string;
  nomeCliente?: string;
  whatsapp_cliente?: string;
  whatsappCliente?: string;
  telefone_cliente?: string;
  cpf_cliente?: string;
  cpfCliente?: string;
  data: string;
  horarios: string[] | string;
  hora_inicio?: string;
  horaInicio?: string;
  hora_fim?: string;
  horaFim?: string;
  valor_total?: number | string;
  valorTotal?: number | string;
  valor_sinal?: number | string;
  valorSinal?: number | string;
  valor_pendente?: number | string;
  valorPendente?: number | string;
  status: string;
  status_whatsapp?: string;
  statusWhatsApp?: string;
  criada_em?: string;
  criadaEm?: string;
  esporte?: string | null;
  observacoes?: string | null;
}

/**
 * Converte um registro do banco de dados (snake_case ou camelCase) para a entidade Reserva.
 */
export function rowToReserva(row: ReservaDbRow): Reserva {
  let horariosArray: string[] = [];
  if (Array.isArray(row.horarios)) {
    horariosArray = row.horarios;
  } else if (typeof row.horarios === "string") {
    try {
      const parsed = JSON.parse(row.horarios);
      if (Array.isArray(parsed)) {
        horariosArray = parsed;
      }
    } catch {
      horariosArray = row.horarios.replace(/[{}]/g, "").split(",").map((s) => s.trim()).filter(Boolean);
    }
  }

  const horaInicio =
    row.hora_inicio ??
    row.horaInicio ??
    (horariosArray.length > 0 ? horariosArray[0] : "08:00");

  const horaFim =
    row.hora_fim ??
    row.horaFim ??
    (horariosArray.length > 0
      ? `${String(parseInt(horariosArray[horariosArray.length - 1], 10) + 1).padStart(2, "0")}:00`
      : "09:00");

  return {
    id: row.id,
    quadraId: row.quadra_id ?? row.quadraId ?? "",
    nomeCliente: row.nome_cliente ?? row.nomeCliente ?? "",
    whatsappCliente:
      row.whatsapp_cliente ??
      row.whatsappCliente ??
      row.telefone_cliente ??
      "",
    cpfCliente: row.cpf_cliente ?? row.cpfCliente ?? "",
    data: typeof row.data === "string" ? row.data.split("T")[0] : String(row.data),
    horarios: horariosArray,
    horaInicio,
    horaFim,
    valorTotal: Number(row.valor_total ?? row.valorTotal ?? 0),
    valorSinal: Number(row.valor_sinal ?? row.valorSinal ?? 0),
    valorPendente: Number(row.valor_pendente ?? row.valorPendente ?? 0),
    status: (row.status as StatusReserva) || "em_processamento",
    statusWhatsApp: (row.status_whatsapp ?? row.statusWhatsApp ?? "nao_enviado") as StatusWhatsApp,
    criadaEm: row.criada_em ?? row.criadaEm ?? new Date().toISOString(),
    esporte: (row.esporte as Esporte) || undefined,
    observacoes: row.observacoes || undefined,
  };
}

/**
 * Converte um objeto parcial ou completo de Reserva para o payload em snake_case esperado pelo PostgreSQL.
 */
export function reservaToRow(reserva: Partial<Reserva>): Record<string, unknown> {
  const row: Record<string, unknown> = {};

  if (reserva.id !== undefined) row.id = reserva.id;
  if (reserva.quadraId !== undefined) row.quadra_id = reserva.quadraId;
  if (reserva.nomeCliente !== undefined) row.nome_cliente = reserva.nomeCliente;
  if (reserva.whatsappCliente !== undefined) {
    row.whatsapp_cliente = reserva.whatsappCliente;
    row.telefone_cliente = reserva.whatsappCliente;
  }
  if (reserva.cpfCliente !== undefined) row.cpf_cliente = reserva.cpfCliente;
  if (reserva.data !== undefined) row.data = reserva.data;
  if (reserva.horarios !== undefined) row.horarios = reserva.horarios;
  if (reserva.horaInicio !== undefined) row.hora_inicio = reserva.horaInicio;
  if (reserva.horaFim !== undefined) row.hora_fim = reserva.horaFim;
  if (reserva.valorTotal !== undefined) row.valor_total = reserva.valorTotal;
  if (reserva.valorSinal !== undefined) row.valor_sinal = reserva.valorSinal;
  if (reserva.valorPendente !== undefined) row.valor_pendente = reserva.valorPendente;
  if (reserva.status !== undefined) row.status = reserva.status;
  if (reserva.statusWhatsApp !== undefined) row.status_whatsapp = reserva.statusWhatsApp;
  if (reserva.criadaEm !== undefined) row.criada_em = reserva.criadaEm;
  if (reserva.esporte !== undefined) row.esporte = reserva.esporte ?? null;
  if (reserva.observacoes !== undefined) row.observacoes = reserva.observacoes ?? null;

  return row;
}

import { supabase, isSupabaseConfigured } from "./client";
import { rowToReserva, reservaToRow, type ReservaDbRow } from "./types";
import type { Reserva } from "@/store/useReservasStore";

const TABELA_RESERVAS = "reservas";

/**
 * Busca todas as reservas cadastradas no Supabase.
 */
export async function fetchReservasSupabase(): Promise<Reserva[] | null> {
  if (!isSupabaseConfigured()) {
    return null;
  }

  try {
    const { data, error } = await supabase
      .from(TABELA_RESERVAS)
      .select("*")
      .order("criada_em", { ascending: false });

    if (error) {
      console.error("[Supabase] Erro ao carregar reservas:", error.message);
      return null;
    }

    return (data as ReservaDbRow[]).map(rowToReserva);
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao buscar reservas:", err);
    return null;
  }
}

/**
 * Insere uma nova reserva no banco de dados Supabase.
 */
export async function inserirReservaSupabase(reserva: Reserva): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const row = reservaToRow(reserva);
    const { error } = await supabase.from(TABELA_RESERVAS).insert([row]);

    if (error) {
      console.error("[Supabase] Erro ao inserir reserva:", error.message);
      return false;
    }

    return true;
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao inserir reserva:", err);
    return false;
  }
}

/**
 * Atualiza campos de uma reserva existente no Supabase.
 */
export async function atualizarReservaSupabase(
  id: string,
  dados: Partial<Reserva>
): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const row = reservaToRow(dados);
    const { error } = await supabase
      .from(TABELA_RESERVAS)
      .update(row)
      .eq("id", id);

    if (error) {
      console.error(`[Supabase] Erro ao atualizar reserva ${id}:`, error.message);
      return false;
    }

    return true;
  } catch (err) {
    console.error(`[Supabase] Falha inesperada ao atualizar reserva ${id}:`, err);
    return false;
  }
}

/**
 * Remove uma reserva do banco de dados Supabase.
 */
export async function removerReservaSupabase(id: string): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const { error } = await supabase
      .from(TABELA_RESERVAS)
      .delete()
      .eq("id", id);

    if (error) {
      console.error(`[Supabase] Erro ao remover reserva ${id}:`, error.message);
      return false;
    }

    return true;
  } catch (err) {
    console.error(`[Supabase] Falha inesperada ao remover reserva ${id}:`, err);
    return false;
  }
}

/**
 * Cria uma inscrição Realtime para escutar inserções, atualizações e deleções
 * na tabela 'reservas' em tempo real.
 */
export function subscreverReservasSupabase(
  onInsert: (reserva: Reserva) => void,
  onUpdate: (reserva: Reserva) => void,
  onDelete: (id: string) => void
) {
  if (!isSupabaseConfigured()) {
    return () => {};
  }

  const canal = supabase
    .channel("mudancas-reservas-realtime")
    .on(
      "postgres_changes",
      {
        event: "INSERT",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const nova = rowToReserva(payload.new as ReservaDbRow);
        onInsert(nova);
      }
    )
    .on(
      "postgres_changes",
      {
        event: "UPDATE",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const atualizada = rowToReserva(payload.new as ReservaDbRow);
        onUpdate(atualizada);
      }
    )
    .on(
      "postgres_changes",
      {
        event: "DELETE",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const idDeletado = (payload.old as { id?: string })?.id;
        if (idDeletado) {
          onDelete(idDeletado);
        }
      }
    )
    .subscribe();

  return () => {
    supabase.removeChannel(canal);
  };
}

/**
 * Store global — Zustand com sincronização com Supabase (PostgreSQL)
 * e fallback em LocalStorage.
 * ATENÇÃO: Componentes de UI não devem importar este arquivo diretamente.
 * Use o hook de abstração: @/hooks/useReservasService
 */

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { Esporte } from "@/lib/quadras";

// ─── Tipos ────────────────────────────────────────────────────────────────────

export type StatusReserva =
  | "em_processamento" // lock temporário durante o checkout
  | "pendente"         // sinal pago, restante a pagar no dia
  | "confirmada"       // pagamento do sinal confirmado
  | "cancelada";       // reserva cancelada

export type StatusWhatsApp = "nao_enviado" | "enviado" | "falhou";

export interface Reserva {
  id: string;
  quadraId: string;

  // Identificação do cliente
  nomeCliente: string;
  whatsappCliente: string;
  cpfCliente: string;

  // Agendamento
  data: string;        // "YYYY-MM-DD"
  horarios: string[];  // ex: ["13:00", "14:00", "15:00"]
  horaInicio: string;  // primeiro slot
  horaFim: string;     // última hora + 1h (ex: "16:00")

  // Financeiro
  valorTotal: number;
  valorSinal: number;    // 40% do total
  valorPendente: number; // 60% do total

  // Estado
  status: StatusReserva;
  statusWhatsApp: StatusWhatsApp;
  criadaEm: string; // ISO datetime

  // Opcionais
  esporte?: Esporte;
  observacoes?: string;
}

// ─── State & Actions ──────────────────────────────────────────────────────────

interface ReservasState {
  reservas: Reserva[];
  isLoadedFromDb: boolean;

  // Mutations
  setReservas: (reservas: Reserva[]) => void;
  adicionarReserva: (reserva: Reserva) => void;
  atualizarReserva: (id: string, dados: Partial<Reserva>) => void;
  removerReserva: (id: string) => void;

  // Computed helpers (usados pelo service)
  getReservaById: (id: string) => Reserva | undefined;
  getReservasPorData: (data: string) => Reserva[];
}

// ─── Store ────────────────────────────────────────────────────────────────────

export const useReservasStore = create<ReservasState>()(
  persist(
    (set, get) => ({
      reservas: [],
      isLoadedFromDb: false,

      setReservas: (reservas) =>
        set({ reservas, isLoadedFromDb: true }),

      adicionarReserva: (reserva) =>
        set((state) => {
          const existe = state.reservas.some((r) => r.id === reserva.id);
          if (existe) {
            return {
              reservas: state.reservas.map((r) =>
                r.id === reserva.id ? reserva : r
              ),
            };
          }
          return { reservas: [reserva, ...state.reservas] };
        }),

      atualizarReserva: (id, dados) =>
        set((state) => ({
          reservas: state.reservas.map((r) =>
            r.id === id ? { ...r, ...dados } : r
          ),
        })),

      removerReserva: (id) =>
        set((state) => ({
          reservas: state.reservas.filter((r) => r.id !== id),
        })),

      getReservaById: (id) => get().reservas.find((r) => r.id === id),

      getReservasPorData: (data) =>
        get().reservas.filter((r) => r.data === data),
    }),
    {
      name: "reservei-v2", // versão da chave no LocalStorage (usada como cache/fallback)
    }
  )
);

/**
 * Camada de abstração entre a UI e o banco de dados Supabase (com sincronização em tempo real).
 * Nenhum componente de UI deve importar o Zustand ou Supabase diretamente.
 * Este hook é o único ponto de acesso ao estado de reservas.
 */

